meta.script:
{
  "@context":"https://schema.org",
  "@type":"FAQPage",
  "mainEntity":[
    {"@type":"Question","name":"Who owns the asset under a chattel mortgage in Australia?",
     "acceptedAnswer":{"@type":"Answer","text":"Your business owns the asset from the date of purchase. The lender registers a security interest on the PPSR until the loan is repaid, after which the interest is released."}},
    {"@type":"Question","name":"Can I claim the GST on a chattel mortgage?",
     "acceptedAnswer":{"@type":"Answer","text":"A GST-registered business can generally claim the GST contained in the asset price as an input tax credit on its next Business Activity Statement, rather than spreading it across the term."}},
    {"@type":"Question","name":"What is a balloon payment on a chattel mortgage?",
     "acceptedAnswer":{"@type":"Answer","text":"A balloon is a lump sum left at the end of the term. It lowers monthly repayments but you still owe the residual amount, which you pay out, refinance or settle when you sell the asset."}}
  ]
}
